/// <summary>
/// CB521_ExciseRegister 
/// Service class for excise lodgement number update with multithread
/// </summary>
class METExciseLodgementUpdateService extends SysOperationServiceBase
{
    public List lodgement = new List(Types::Container);

}

Method.Source:
/// <summary>
/// Process method to initiate the multi thread for business logic
/// </summary>
/// <param name = "_contract">Contract class reference</param>
public void process(METExciseLodgementUpdateContract     _contract)
{
    this.processCP(_contract);
    this.processOriginal(_contract);
}

    /// <summary>
    /// Process method to initiate the multi thread for business logic
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    public void processOriginal(METExciseLodgementUpdateContract     _contract)
    {
        BatchHeader                     batchHeader;
        SysOperationServiceController   runTaskController;
        METExciseInformationTable       metExciseInformationTable;
        METExciseRegisterOriginTypes    metExciseRegisterOriginTypes;
        METExciseLodgementUpdateContract     contract;

        while select InventTransType, ItemId, SiteId from metExciseInformationTable
            group by ItemId, SiteId, InventTransType
                where metExciseInformationTable.Lodgement == ''
            exists join metExciseRegisterOriginTypes
                where metExciseRegisterOriginTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                        metExciseRegisterOriginTypes.UpdateLodgement == NoYes::Yes
        {
            if (this.isExecutingInBatch())
            {
                runTaskController = new SysOperationServiceController(classStr(METExciseLodgementUpdateService), methodStr(METExciseLodgementUpdateService, runExciseLodgementUpdate));
            
                contract = runTaskController.getDataContractObject('_contract');

                if (!batchHeader)
                {
                    batchHeader = this.getCurrentBatchHeader();
                }

                contract.parmReferenceId(metExciseInformationTable.InventTransType);
                contract.parmItemId(metExciseInformationTable.ItemId);
                contract.parmSiteId(metExciseInformationTable.SiteId);

                batchHeader.addRuntimeTask(runTaskController, this.getCurrentBatchTask().RecId);
            }
            else
            {
                contract = new METExciseLodgementUpdateContract();

                contract.parmReferenceId(metExciseInformationTable.InventTransType);
                contract.parmItemId(metExciseInformationTable.ItemId);
                contract.parmSiteId(metExciseInformationTable.SiteId);

                this.runExciseLodgementUpdate(contract);
            }
        }

        if (batchHeader)
        {
            batchHeader.save();
        }
    }

    /// <summary>
    /// Processes catch weight excise lodgement updates by grouping unlodged excise records
    /// and updating them with corresponding lodgement values.
    /// </summary>
    /// <param name="_contract">The contract containing context for the lodgement update process.</param>
    public void processCP(METExciseLodgementUpdateContract     _contract)
    {
        METExciseInformationTable metExciseInformationTable, metExciseInformationTableSource;
        METExciseRegisterOriginTypes metExciseRegisterOriginTypes;

        while select InventTransType, ItemId, SiteId from metExciseInformationTable
            group by ItemId, SiteId, InventTransType
                where metExciseInformationTable.Lodgement == ''
            exists join metExciseRegisterOriginTypes
                where metExciseRegisterOriginTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                        (metExciseRegisterOriginTypes.UpdateCPLodgement == NoYes::Yes && metExciseRegisterOriginTypes.ReferenceId != InventTransType::Sales)
                        || (metExciseRegisterOriginTypes.UpdateCPLodgement == NoYes::No && metExciseRegisterOriginTypes.ReferenceId == InventTransType::Sales)
        {
            ttsbegin;
            this.processMatchingExciseLines(metExciseInformationTable.InventTransType, metExciseInformationTable.ItemId, metExciseInformationTable.SiteId);
            ttscommit;
        }
    }

    /// <summary>
    /// Updates excise information records with concatenated lodgement values
    /// based on matching transfer journal lines for a given item, site, and transaction type.
    /// </summary>
    /// <param name="_inventTransType">The inventory transaction type to filter records.</param>
    /// <param name="_itemId">The item ID to filter records.</param>
    /// <param name="_siteId">The site ID to filter records.</param>
    private void processMatchingExciseLines(InventTransType _inventTransType, ItemId _itemId, InventSiteId _siteId)
    {
        METExciseInformationTable metExciseInformationTableSource;

        if (_inventTransType == InventTransType::TransferOrderShip)
        {
            InventTransferJourLine inventTransferJourLine;

            while select forupdate metExciseInformationTableSource
                where metExciseInformationTableSource.InventTransType == _inventTransType &&
                  metExciseInformationTableSource.ItemId == _itemId &&
                  metExciseInformationTableSource.SiteId == _siteId &&
                  metExciseInformationTableSource.Lodgement == ''
            join RecId from inventTransferJourLine
                where inventTransferJourLine.InventTransId == metExciseInformationTableSource.InventTransId
            {
                METLodgementExt concatenatedLodgement = this.getConcatenatedLodgements(inventTransferJourLine.RecId);
                
                if (concatenatedLodgement)
                {
                    metExciseInformationTableSource.LodgementAndQtyCon = this.getAggregatedLodgements(inventTransferJourLine.RecId);
                    metExciseInformationTableSource.Lodgement = concatenatedLodgement;
                    metExciseInformationTableSource.update();
                    info(strFmt("@MET:LodgmentUpdate", _itemId, _siteId));
                }
            }
        }
        else if (_inventTransType == InventTransType::Purch)
        {
            PurchLine purchLine;
            METPurchLine metPurchLine;

            while select forupdate metExciseInformationTableSource
                where metExciseInformationTableSource.InventTransType == _inventTransType &&
                  metExciseInformationTableSource.ItemId == _itemId &&
                  metExciseInformationTableSource.SiteId == _siteId &&
                  metExciseInformationTableSource.Lodgement == '' &&
                  metExciseInformationTableSource.InventoryQty < 0
            join RecId from purchLine
                where purchLine.InventTransId == metExciseInformationTableSource.InventTransId
            join Lodgement, BottleSupplied from metPurchLine
                where metPurchLine.PurchLine == purchLine.RecId
                && metPurchLine.Lodgement != ''
            {
                metExciseInformationTableSource.LodgementAndQtyCon = this.buildPairContainer(metPurchLine.Lodgement, metPurchLine.BottleSupplied, metPurchLine.ReferenceNumber);
                metExciseInformationTableSource.Lodgement = metPurchLine.Lodgement;
                metExciseInformationTableSource.update();
                info(strFmt("@MET:LodgmentUpdate", _itemId, _siteId));
            }
        }
        else if (_inventTransType == InventTransType::Sales)
        {
            SalesLine salesLine;
            MetSalesLine metSalesLine;

            while select forupdate metExciseInformationTableSource
                where metExciseInformationTableSource.InventTransType == _inventTransType &&
                  metExciseInformationTableSource.ItemId == _itemId &&
                  metExciseInformationTableSource.SiteId == _siteId &&
                  metExciseInformationTableSource.Lodgement == '' &&
                  metExciseInformationTableSource.InventoryQty < 0 
            join RecId from salesLine
                where salesLine.InventTransId == metExciseInformationTableSource.InventTransId
            join Lodgement, BottleSupplied from metSalesLine
                where metSalesLine.SalesLine == SalesLine.RecId
                  && metSalesLine.Lodgement != ''
            {
                metExciseInformationTableSource.LodgementAndQtyCon = this.buildPairContainer(metSalesLine.Lodgement, metSalesLine.BottleSupplied, metSalesLine.ReferenceNumber);
                metExciseInformationTableSource.Lodgement = metSalesLine.Lodgement;
                metExciseInformationTableSource.update();
                info(strFmt("@MET:LodgmentUpdate", _itemId, _siteId));
            }
        }
    }

    /// <summary>
    /// Retrieves and concatenates all lodgement values associated with a given transfer journal line.
    /// </summary>
    /// <param name="_inventTransferJourLineRecId">The RecId of the transfer journal line.</param>
    /// <returns>A comma-separated string of lodgement values.</returns>
    private str getConcatenatedLodgements(RecId _inventTransferJourLineRecId)
    {
        METTransferOrderLodgements transferOrderLodgements;
        str result = "";

        while select Lodgement from transferOrderLodgements
            where transferOrderLodgements.ReferenceId == _inventTransferJourLineRecId
        {
            if (transferOrderLodgements.Lodgement)
            {
                result += result == ""
                ? transferOrderLodgements.Lodgement
                : strFmt(", %1", transferOrderLodgements.Lodgement);
            }
        }

        return result;
    }

    /// <summary>
    /// Retrieves a container of LodgementId and aggregated BottleSupplied values
    /// for a given transfer journal line using GROUP BY.
    /// </summary>
    /// <param name="_inventTransferJourLineRecId">The RecId of the transfer journal line.</param>
    /// <returns>A container where each element is [LodgementId, SumBottleSupplied].</returns>
    private container getAggregatedLodgements(RecId _inventTransferJourLineRecId)
    {
        METTransferOrderLodgements transferOrderLodgements;
        container result;

        while select Lodgement, sum(LodgementQty), OrderNumber from transferOrderLodgements
            group by transferOrderLodgements.Lodgement, transferOrderLodgements.OrderNumber
            where transferOrderLodgements.ReferenceId == _inventTransferJourLineRecId
        {
            result += [transferOrderLodgements.Lodgement, transferOrderLodgements.LodgementQty, transferOrderLodgements.OrderNumber];
        }

        return result;
    }

    /// <summary>
    /// Builds a paired container structure from two comma‑separated input strings.
    /// </summary>
    /// <remarks>
    /// This method accepts two string inputs:
    ///     1. _names      – comma‑separated list of identifiers (e.g., "Lod1,Lod2,Lod3")
    ///     2. _quantities – comma‑separated list of numeric values (e.g., "10,20,30")
    ///
    /// Both lists must contain the same number of elements.
    /// The method converts each list into a container and combines them into a
    /// result container in the format:
    ///     [[name1, qty1], [name2, qty2], ..., [nameN, qtyN]]
    ///
    /// Example:
    ///     Input:  _names = "A,B,C"
    ///             _quantities = "5,10,15"
    ///     Output: [[A,5], [B,10], [C,15]]
    ///
    /// return if the number of elements in the two lists do not match.
    /// </remarks>
    /// <param name="_names">Comma‑separated list of string identifiers.</param>
    /// <param name="_quantities">Comma‑separated list of quantities.</param>
    /// <param name="_orderReferences">Comma-separated list of order references.</param>
    /// <returns>A container of paired values.</returns>
    private container buildPairContainer(METLodgementExt _names, METLodgementExt _quantities, METLodgementExt   _orderReferences)
    {
        container result;
        container nameList  = str2con(_names, ",");
        container qtyList   = str2con(_quantities, ",");
        container orderRefList   = str2con(_orderReferences, ",");
        int i, counter;

        counter = conLen(nameList);

        // Ensure both lists have the same number of elements
        if (counter != conLen(qtyList))
        {
            return conNull();
        }

        for (i = 1; i <= counter; i++)
        {
            result += [conPeek(nameList, i), str2Num(conPeek(qtyList, i)), conPeek(orderRefList, i)];
        }

        return result;
    }

/// <summary>
/// Updates the lodgement number on the Excise Information table for the specified contract.
/// Handles both direct and batch execution, and manages available quantity and lodgement assignment logic.
/// </summary>
/// <param name = "_contract">Contract class</param>
public void runExciseLodgementUpdate(METExciseLodgementUpdateContract _contract)
{
    this.runExciseLodgementUpdateActual(_contract);
}

    /// <summary>
    /// Method to use to update the lodgement number on Excise information table
    /// </summary>
    /// <param name = "_contract">METExciseLodgementUpdateContract contract class </param>
    /// <param name = "_refId">InventTransRefId type</param>
    public void runExciseLodgementUpdateActual(METExciseLodgementUpdateContract _contract, InventTransRefId _refId = '')
    {
        METExciseInformationTable       metExciseInformationTablePO;
        METExciseInformationTable       metExciseInformationTable;
        METAvailableQty                 purchAvailableQty;
        METAvailableQty                 purchAvailableQtyOrig;
        METLodgement                    metLodgement;

        try
        {
            if (_refId)
            {
                while select forupdate metExciseInformationTable
                    where metExciseInformationTable.InventTransType == _contract.parmReferenceId()  &&
                        metExciseInformationTable.ItemId == _contract.parmItemId() &&
                        metExciseInformationTable.SiteId == _contract.parmSiteId() &&
                        metExciseInformationTable.Lodgement == '' &&
                        metExciseInformationTable.ReferenceNumber == _refId
                {
                    ttsbegin;
                    this.runExciseLodgementUpdateActualV1(metExciseInformationTable);
                    ttscommit;
                }
            }
            else
            {
                while select forupdate metExciseInformationTable
                    where metExciseInformationTable.InventTransType == _contract.parmReferenceId()  &&
                        metExciseInformationTable.ItemId == _contract.parmItemId() &&
                        metExciseInformationTable.SiteId == _contract.parmSiteId() &&
                        metExciseInformationTable.Lodgement == ''
                {
                    ttsbegin;
                    this.runExciseLodgementUpdateActualV1(metExciseInformationTable);
                    ttscommit;
                }
            }
        }
        catch
        {
            exceptionTextFallThrough();
        }
        
    }

    /// <summary>
    /// Method to use to update the lodgement number on Excise information table
    /// </summary>
    /// <param name = "_contract">METExciseLodgementUpdateContract contract class </param>
    public void runExciseLodgementUpdateActualV1(METExciseInformationTable _metExciseInformationTable)
    { 
        METExciseInformationTable       metExciseInformationTablePO;
        METExciseInformationTable       metExciseInformationTable = _metExciseInformationTable;
        METAvailableQty                 purchAvailableQty;
        METAvailableQty                 purchAvailableQtyOrig;
        METLodgementEXT                 metLodgement;
        List                            lodgementList = new List(Types::Container);

        container lodgementQtyCon;

        if (_metExciseInformationTable.InventoryQty < 0) // Only for issue transactions
        {
            select sum(AvailableQty) from metExciseInformationTablePO
                order by CreatedDateTime
                    where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                        metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                        metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId &&
                        metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId &&
                        metExciseInformationTablePO.AvailableQty > 0 &&
                        metExciseInformationTablePO.LodgementClosed == NoYes::No;

            if (metExciseInformationTablePO.AvailableQty < abs(_metExciseInformationTable.InventoryQty))
            {
                Error(strFmt("@MET:LodgementInsufficient", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
                return;
            }
        }

        metExciseInformationTablePO = null;

        select forupdate metExciseInformationTablePO
            order by CreatedDateTime
                where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                    metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                    metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId &&
                    metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId &&
                    metExciseInformationTablePO.AvailableQty > 0 &&
                    metExciseInformationTablePO.LodgementClosed == NoYes::No;

        if (metExciseInformationTablePO.RecId != 0)
        {
            purchAvailableQty  =  metExciseInformationTablePO.AvailableQty + metExciseInformationTable.InventoryQty;
            metLodgement = metExciseInformationTablePO.Lodgement;

            if (purchAvailableQty >= 0)
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(metExciseInformationTable.InventoryQty)];

                metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                if (purchAvailableQty == 0)
                {
                    metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                }
                metExciseInformationTablePO.update();

                metExciseInformationTable.Lodgement = metExciseInformationTablePO.Lodgement;
                metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                metExciseInformationTable.update();
            }
            else
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(metExciseInformationTablePO.AvailableQty), metExciseInformationTablePO.ReferenceNumber];

                metExciseInformationTablePO.AvailableQty = 0;
                metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                metExciseInformationTablePO.update();

                do
                {
                    next metExciseInformationTablePO;

                    if (metExciseInformationTablePO.RecId == 0)
                    {
                        Error(strFmt("@MET:LodgementValidation", metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
                        break;
                    }
                    purchAvailableQtyOrig = abs(purchAvailableQty);
                    purchAvailableQty  =  metExciseInformationTablePO.AvailableQty + purchAvailableQty;

                    metLodgement = metLodgement + ','+  metExciseInformationTablePO.Lodgement;
                           
                    if (purchAvailableQty >= 0)
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, purchAvailableQtyOrig, metExciseInformationTablePO.ReferenceNumber];

                        metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                        if (purchAvailableQty == 0)
                        {
                            metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                        }
                        metExciseInformationTablePO.update();

                        break;
                    }
                    else
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, metExciseInformationTablePO.AvailableQty, metExciseInformationTablePO.ReferenceNumber];

                        metExciseInformationTablePO.AvailableQty = 0;
                        metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                        metExciseInformationTablePO.update();
                    }

                    lodgementList.addEnd(lodgementQtyCon);
                }
                while (purchAvailableQty < 0);

                metExciseInformationTable.reread();
                metExciseInformationTable.Lodgement = metLodgement;
                metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                metExciseInformationTable.update();
            }

            lodgement = lodgementList;

            info(strFmt("@MET:LodgmentUpdate", metExciseInformationTable.ItemId, metExciseInformationTable.SiteId));
        }
        else if (metExciseInformationTable.InventoryQty > 0 && (metExciseInformationTable.InventTransType == InventTransType::Sales ||
                metExciseInformationTable.InventTransType == InventTransType::InventCounting))
        {
            select firstonly forupdate metExciseInformationTablePO
                order by metExciseInformationTablePO.ModifiedDateTime desc
                where metExciseInformationTablePO.InventTransType == InventTransType::Purch
                && metExciseInformationTablePO.ItemId == metExciseInformationTable.ItemId
                && metExciseInformationTablePO.SiteId == metExciseInformationTable.SiteId
                && metExciseInformationTablePO.InventoryQty > 0;

            if (metExciseInformationTablePO.RecId != 0)
            {
                metExciseInformationTablePO.AvailableQty += metExciseInformationTable.InventoryQty;
                metExciseInformationTablePO.LodgementClosed = NoYes::No;
                ttsbegin;
                metExciseInformationTablePO.update();

                metExciseInformationTable.reread();
                metExciseInformationTable.Lodgement = metExciseInformationTablePO.Lodgement;
                metExciseInformationTable.LodgementAndQtyCon = [metExciseInformationTablePO.Lodgement, metExciseInformationTable.InventoryQty, metExciseInformationTable.ReferenceNumber];
                metExciseInformationTable.update();
                ttscommit;
            }
        }
    }

/// <summary>
/// Lodgement calculated value.
/// </summary>
/// <returns>METLodgement list</returns>
public List getMetLodgement()
{
    return lodgement;
}
